import{c as t,Q as o,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Competitors and clubs","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/competitors-clubs-teams.md","filePath":"user/event-setup/competitors-clubs-teams.md"}'),a={name:"user/event-setup/competitors-clubs-teams.md"};function s(i,e,h,l,d,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="competitors-and-clubs" tabindex="-1">Competitors and clubs <a class="header-anchor" href="#competitors-and-clubs" aria-label="Permalink to &quot;Competitors and clubs&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers managing the list of people taking part.</p><p>This page covers the <strong>Competitors</strong> and <strong>Clubs</strong> views and the competitor edit dialog. As with classes and courses, most events get their competitors from an import — see <a href="./import-event-data">Importing event data</a> — so you&#39;re usually reviewing and adjusting rather than typing everyone in by hand.</p><blockquote><p>Relay and team events organise competitors into teams with legs. Teams will be covered in a separate topic.</p></blockquote><h2 id="the-competitors-page" tabindex="-1">The Competitors page <a class="header-anchor" href="#the-competitors-page" aria-label="Permalink to &quot;The Competitors page&quot;">​</a></h2><p>Navigate to <strong>Competitors</strong> in the <strong>Event Data</strong> section of the side menu.</p><p>The table shows one row per competitor with these columns (some appear conditionally):</p><ul><li><strong>Competitor</strong> — the competitor&#39;s name. Click it to open the edit dialog.</li><li><strong>Class</strong> — an inline dropdown. Change it here to move the competitor to another class without opening the dialog. Pick <strong>No class</strong> to unassign.</li><li><strong>Club</strong> — the club they represent (read-only here; set it in the edit dialog or via import).</li><li><strong>Start time</strong> — the effective allocated start, annotated with where it came from — <code>10:30:00 (individual)</code>, <code>(class)</code>, or <code>(event)</code>. See <a href="./start-times">Start times</a>.</li><li><strong>Card</strong> — an inline field for the card number. Type a new number to reassign; it saves automatically. A yellow <strong>Duplicate</strong> warning appears when the same card number is on more than one competitor.</li><li><strong>Ranking</strong> — the competitor&#39;s place on an external ranking list; see <a href="#ranking">Ranking</a> below. <strong>Hidden until you turn it on</strong>: use the columns button at the right-hand end of the header row and tick <strong>Ranking</strong> under <strong>Show columns</strong>. Sort it ascending and you get the seeding order: rank 1 at the top, and everyone with no ranking sunk to the bottom rather than floating above rank 1.</li><li><strong>Last seen</strong> — the most recent radio punch for this competitor, shown only once radio punches are arriving. Relevant during the event rather than at setup; see <a href="./../running-the-event/radio-punches">Radio punches</a>.</li><li><strong>Status</strong> — the competitor&#39;s <a href="./../reference/status-and-race-time">status</a>. After a download, a small course badge shows which course in the pool produced the result.</li></ul><p>Filter the table with <strong>Search Name or Card</strong> (matches the name <em>and</em> the card number), the <strong>Status</strong> filter, or the <strong>Class</strong> filter. The status filter includes a synthetic <strong>OK - pending download</strong> option that picks out competitors who are provisionally OK on radio punches but whose card hasn&#39;t been downloaded yet.</p><p>The <strong>Actions</strong> menu (top right) has:</p><ul><li><strong>Import</strong> — open the <strong>Import Data</strong> dialog. See <a href="./import-event-data">Importing event data</a>.</li><li><strong>Add</strong> — create a new competitor by hand (see below).</li><li><strong>Set competitors DNS</strong> — bulk-mark non-starters as Did Not Start (see <a href="#marking-non-starters-set-dns">Marking non-starters</a>).</li><li><strong>Bulk edit</strong> — edit many competitors at once in a grid (see <a href="#editing-many-competitors-at-once">Editing many competitors at once</a>).</li><li><strong>Export entry list</strong> — write who has entered to a file, in one of three formats. See <a href="#exporting-the-entry-list">Exporting the entry list</a>.</li><li><strong>Delete all competitors</strong> — empty the list (see <a href="#clearing-the-whole-competitor-list">Clearing the whole competitor list</a>).</li></ul><h2 id="adding-or-editing-a-competitor" tabindex="-1">Adding or editing a competitor <a class="header-anchor" href="#adding-or-editing-a-competitor" aria-label="Permalink to &quot;Adding or editing a competitor&quot;">​</a></h2><p>Click <strong>Actions → Add</strong> to create one, or click a competitor&#39;s name to edit. The <strong>Add Competitor</strong> / edit dialog opens.</p><p>When creating, you get a single form:</p><ul><li><strong>First name</strong> and <strong>Surname</strong> — at least one is required. As you type, Manager suggests matches from the <a href="./../reference/competitor-registry">Competitor Registry</a>; picking a person fills in their club, card number, and Eventor/IOF IDs.</li><li><strong>Card number</strong> Numeric only. (During a card download this field may be pre-filled and locked.)</li><li><strong>Eventor ID</strong> and <strong>IOF ID</strong> — optional external identifiers, used by exports and re-imports.</li><li><strong>Class</strong> — the class they run. Pick <strong>No class</strong> to leave them unassigned.</li><li><strong>Club</strong> — the club they represent, or <strong>No club</strong>.</li><li><strong>Course</strong> — appears only when the chosen class has <strong>two or more courses</strong> in its pool. Leave it on <strong>Any in the course pool</strong> to let Manager pick the best-matching course automatically, or lock the competitor to a specific course. See <a href="./classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">Course pools and locking</a>.</li><li><strong>Start time</strong> — an individual allocated start, plus an <strong>On start punch</strong> option controlling whether a start-box punch is allowed to override it. The full rules live in <a href="./start-times">Start times</a>.</li></ul><p>Click <strong>Save</strong>.</p><h3 id="editing-an-existing-competitor" tabindex="-1">Editing an existing competitor <a class="header-anchor" href="#editing-an-existing-competitor" aria-label="Permalink to &quot;Editing an existing competitor&quot;">​</a></h3><p>Opening an existing competitor gives a wider dialog with tabs down the left:</p><ul><li><strong>Details</strong> — the create form&#39;s fields plus a few that only make sense once a competitor exists, among them <strong>Bib</strong>, <strong>Ranking</strong> (see <a href="#ranking">Ranking</a> below) and <strong>Notes</strong> (see <a href="#notes">Notes</a>). In edit mode changes <strong>save automatically</strong>: text fields a moment after you stop typing, dropdowns immediately. There&#39;s no Save button — just close the dialog when you&#39;re done.</li><li><strong>Result</strong> — the competitor&#39;s <a href="./../reference/status-and-race-time">status</a>, resolved course, and race time. You can override the status here; Manager won&#39;t let you reset a competitor to <strong>None</strong> if there&#39;s evidence they started (a download, radio punches, or a station-memory punch).</li><li><strong>Radio Punches</strong>, <strong>Download</strong>, <strong>Unit Downloads</strong>, <strong>Splits Print</strong>, <strong>Mistakes</strong>, <strong>Overrides</strong> — these relate to running the event and resolving results; they&#39;re covered under <a href="./../running-the-event/card-download">Running the event</a> and <a href="./../running-the-event/resolving-issues">Resolving issues</a>.</li></ul><p>To remove a competitor, open them, go to <strong>Details</strong>, and click the red <strong>Delete</strong> button (bottom-left). Confirm the prompt. Deletion is permanent.</p><h2 id="card-numbers" tabindex="-1">Card numbers <a class="header-anchor" href="#card-numbers" aria-label="Permalink to &quot;Card numbers&quot;">​</a></h2><p>The <strong>Card</strong> column and the <strong>Card number</strong> field hold the number of the card a competitor carries. A few things to know:</p><ul><li><strong>Duplicates are allowed but flagged.</strong> Two competitors can hold the same card number — Manager shows a yellow <strong>Duplicate</strong> warning rather than blocking it. This is normal when a card is shared between two people running in different classes at different times, but a duplicate among people running at the same time will cause a download to land on the wrong competitor, so check any duplicates you didn&#39;t intend.</li><li><strong>A blank card is fine at setup.</strong> A competitor can be entered without a card and have one assigned later — including automatically, when their card is downloaded.</li><li><strong>Hire (rental) cards</strong> have dedicated support. You keep a shared pool of hire-card numbers under <strong>Settings → Hire card registry</strong>; any competitor whose card number is in the pool is automatically flagged as being on a hire card, and you can narrow the list with the <strong>Card type</strong> filter (hire vs own). Anything else you lend — a compass, a map board — is ticked on the competitor&#39;s own <strong>Hire items</strong> tab. See <a href="./../running-the-event/hire-items">Hire items</a>.</li></ul><h2 id="ranking" tabindex="-1">Ranking <a class="header-anchor" href="#ranking" aria-label="Permalink to &quot;Ranking&quot;">​</a></h2><p>A competitor&#39;s <strong>Ranking</strong> is their place on an external ranking list — a national ranking, a squad&#39;s seeding order, whatever list you were handed for this event. <strong>1 is the best-ranked athlete</strong>, and the number gets worse as it grows. Someone who isn&#39;t on the list has no ranking, which Manager shows as a blank rather than a zero.</p><p>It is a <em>place</em>, not a score. A ranking of 4 is better than a ranking of 40, and Manager will never treat a bigger number as better. (World Ranking <strong>points</strong> are the opposite — bigger is better — and are a different thing entirely; Manager doesn&#39;t store them, and won&#39;t read a points column as a ranking.)</p><p>Three things use it:</p><ul><li>The <a href="./start-draw#drawing-by-ranking"><strong>By ranking</strong> start draw</a>, which seeds each class in ranking order.</li><li>The <strong>Ranking</strong> column on this page, off until you turn it on in the columns menu.</li><li>The spectator site: tap a competitor to open their card and the ranking is one of the details listed, for anyone who has one.</li></ul><p>Nothing computes it and nothing changes it behind your back — it&#39;s yours to set. There are three ways to get it in:</p><ol><li><strong>Type it</strong> into the <strong>Ranking</strong> field on the <strong>Details</strong> tab of an existing competitor. It saves as you type, like the rest of that tab. Clear the box to mean &quot;not ranked&quot;.</li><li><strong>Import a ranking list</strong> — the usual route for a whole field. IOF XML, Orienteering JSON and CSV are all accepted; only the CSV asks you which column is which. See <a href="./import-event-data#importing-rankings">Importing rankings</a>.</li><li><strong>From an entry list</strong>, if yours happens to carry one. Most don&#39;t: there is no ranking field in the IOF XML standard, so Manager reads one only from an IOF entry list whose <code>&lt;Score&gt;</code> is explicitly labelled as a rank, and from an Orienteering JSON file. Anything else is left alone.</li></ol><p>Rankings travel <em>out</em> as well: all three of the <a href="#exporting-the-entry-list">entry-list exports</a> carry them, so a list you&#39;ve seeded once can be handed on, or exported and re-imported next season.</p><blockquote><p><strong>Note:</strong> Rankings are held <strong>per event</strong>, not in the <a href="./../reference/competitor-registry">Competitor Registry</a>. That is deliberate — a ranking list is republished every few weeks, so a value remembered from an event three months ago would be quietly wrong. Import the current list for each event that needs one.</p></blockquote><blockquote><p><strong>Tip:</strong> Re-importing an entry list or a start list never wipes rankings you&#39;ve already set. A file that says nothing about a ranking leaves the stored one alone; only a file that actually states one changes it.</p></blockquote><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p><strong>Notes</strong> is a box for whatever you needed to write down about one entry that no other field holds — &quot;paid cash&quot;, &quot;hire card back after the run&quot;, &quot;under 12, running with a parent&quot;, &quot;asked us to hold their car keys&quot;. It runs the full width of the <strong>Details</strong> tab, under <strong>Ranking</strong>, and saves as you type like the rest of that tab.</p><p>Nothing in Manager reads it. It never affects a status, a time, a draw or a result — it is there so the thing you would otherwise have written on a sticky note is somewhere the next person on the desk will find it.</p><p>Two places write the same note:</p><ul><li>The <strong>Details</strong> tab of an existing competitor, as above.</li><li><strong>The registration desk</strong> — the note is a box on each search result, so somebody at the entry table can add one without opening the whole record. The class and the card number are editable there too.</li></ul><p>Notes are held <strong>per event</strong>, like <a href="#ranking">rankings</a> and for a stronger reason: &quot;paid cash&quot; is true of one Saturday, not of a person. They are not kept in the <a href="./../reference/competitor-registry">Competitor Registry</a> and they never follow a runner into next season&#39;s event.</p><blockquote><p><strong>Note:</strong> A note stays inside this event. It is <strong>not</strong> written to any of the <a href="#exporting-the-entry-list">entry-list exports</a> — not the IOF XML, not the Orienteering JSON, not the CSV — and no spectator, kiosk or live-results screen displays it. It does travel in an <a href="./../reference/backup-and-restore">event backup</a>, because a backup is a copy of the whole event.</p></blockquote><blockquote><p><strong>Not a private field, though.</strong> Nothing shows a note to spectators, but the competitor data those screens read does carry it — the same as it carries your <a href="./../reference/settings">custom competitor fields</a> — and that data is readable by anything that can reach this Manager, or the public link if you have pushed the event to the cloud. Write what the next person on the desk needs; don&#39;t write what you would not want a competitor to read.</p></blockquote><blockquote><p><strong>Tip:</strong> Re-importing an entry list never wipes notes, the same way it never wipes rankings: a file that says nothing about a note leaves the stored one alone. Emptying the box yourself does clear it.</p></blockquote><h2 id="start-requests" tabindex="-1">Start requests <a class="header-anchor" href="#start-requests" aria-label="Permalink to &quot;Start requests&quot;">​</a></h2><p>A <strong>start request</strong> is what an entrant asked for when they entered. There are four:</p><ul><li><strong>Early start</strong> — they have to leave.</li><li><strong>Late start</strong> — they are arriving late.</li><li><strong>Away from competitor</strong> — they must not run at the same time as certain other people. Two parents splitting the childminding between them is the usual reason.</li><li><strong>Close to competitor</strong> — they want to go at about the same time as certain other people. A family or a car-load who travelled together and want to leave together.</li></ul><p>The last two name <strong>other people</strong>, and they name a <em>group</em> rather than a partner: a family of three is one arrangement, not two overlapping ones. Set it on one of them and Manager writes the whole arrangement onto every member, so the group reads the same whichever of them you open. Name somebody who is already in a group and the two groups merge, because that is what naming them says.</p><p>Set a request on the <strong>Start</strong> tab of <strong>Edit competitor</strong> — pick the kind, then, for the last two, tick the people it is about. There is also a <strong>Start request</strong> column on this page, off until you turn it on in the columns menu, and a request column in the <a href="#editing-many-competitors-at-once">bulk-edit grid</a>, where the kind can be filled down a selection (the people it names are read-only there).</p><p>Requests also travel in and out of files. An IOF XML entry list, an Orienteering JSON file and both CSV exports all carry them, so an entry system that collects requests can hand them straight over. The people in a group are named as <em>people</em>, never as an id, and Manager matches them back once every entry is in — so somebody named by a file who is not entered leaves the request standing with nobody attached, and tells you so rather than guessing.</p><h3 id="what-manager-does-with-one" tabindex="-1">What Manager does with one <a class="header-anchor" href="#what-manager-does-with-one" aria-label="Permalink to &quot;What Manager does with one&quot;">​</a></h3><p>The <a href="./start-draw#honouring-start-requests">start draw</a> reads it — <strong>Honour start requests</strong> is on by default, so unless you have switched it off, the draw decides <em>who takes which start time</em> accordingly. It moves no class: an early start means first of that person&#39;s own class, not first of the event. A second setting, also on, lets an early or late request be answered with a free minute outside the class&#39;s own window where the event runs on past it, so somebody who asked to start late in a class that finishes at 10:45 can be given 14:00.</p><p>Every screen that shows a request says what was <strong>asked</strong>, never what the person got — honouring is best effort, and a group request in particular is only answered as far as the classes involved allow.</p><blockquote><p><strong>Note:</strong> Requests are held <strong>per event</strong>, not in the <a href="./../reference/competitor-registry">Competitor Registry</a>, for the same reason rankings are. &quot;Has to leave early&quot; is true of one Saturday, not of a person.</p></blockquote><blockquote><p><strong>Tip:</strong> Deleting an entrant takes them out of any group they were in, and the rest keep each other. Anybody the departure leaves on their own loses their request too — a group of one is not an arrangement — and Manager says so, so you can put it back on somebody else if it still applies.</p></blockquote><h2 id="exporting-the-entry-list" tabindex="-1">Exporting the entry list <a class="header-anchor" href="#exporting-the-entry-list" aria-label="Permalink to &quot;Exporting the entry list&quot;">​</a></h2><p><strong>Actions → Export entry list</strong> writes who has entered to a file. There are three formats, and they differ mainly in what they can carry:</p><table tabindex="0"><thead><tr><th>Format</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><strong>Export IOF XML</strong></td><td>Handing the entries to a federation system, or anything else that speaks the IOF standard. Manager writes an IOF 3.0 <code>EntryList</code>, which is what the standard says entries should be exchanged as.</td></tr><tr><td><strong>Export JSON</strong></td><td>Moving the entries to another meshO Manager, or to anything that wants everything Manager knows. This is the fullest of the three — it&#39;s Orienteering JSON, the same format the other JSON exports use.</td></tr><tr><td><strong>Export CSV</strong></td><td>Opening the list in a spreadsheet: to check it, to hand it round, or to edit it and put it back.</td></tr></tbody></table><p>Pick one and the file downloads straight away, named after the event.</p><blockquote><p><strong>Note:</strong> This is an entry list, not a start list — it says who has entered, not when they run or how they got on. None of the three formats carries a start time or a result. To publish start times, use the <strong>Publish</strong> menu on the <a href="./start-draw#the-start-list-tab">Start list tab</a>, which offers the same three formats <em>with</em> the times; for results, see <a href="./../after-the-event/exports">Exporting data</a>.</p></blockquote><h3 id="the-export-is-always-the-whole-event" tabindex="-1">The export is always the whole event <a class="header-anchor" href="#the-export-is-always-the-whole-event" aria-label="Permalink to &quot;The export is always the whole event&quot;">​</a></h3><p><strong>Whatever the list on screen is filtered to, the export contains every competitor in the event.</strong> The search box and the <strong>Class</strong>, <strong>Status</strong> and <strong>Card type</strong> filters are there to help you <em>find</em> somebody — none of them narrows the file. The menu says so above the three formats, because this is the thing about the export most likely to catch you out.</p><p>It works that way on purpose. The failure that would really hurt is handing a federation an entry list with one person in it because you&#39;d searched for a name a minute earlier, with nothing on screen to tell you. Getting the whole list when you wanted a smaller one is obvious the moment you open the file.</p><p><strong>The one exception: a competitor with no class is not exported.</strong> All three formats are organised by class — an entry list says who has entered <em>what</em> — so somebody with no class yet has nowhere to sit in the file, and every export leaves them out. This is the same rule the start list follows. It matters because an entry import that couldn&#39;t work out a competitor&#39;s class still enters them, without one, and warns you at the time. If your export is short by a few people, sort the Competitors list by <strong>Class</strong> and look for the blanks.</p><h3 id="a-mixed-relay-event-asks-which-kind" tabindex="-1">A mixed relay event asks which kind <a class="header-anchor" href="#a-mixed-relay-event-asks-which-kind" aria-label="Permalink to &quot;A mixed relay event asks which kind&quot;">​</a></h3><p>An event with both relay classes and individual classes can&#39;t put both in one file — see <a href="./relay-events#mixed-events-relay-and-individual-classes-together">Mixed events</a>. So Manager asks before it exports: choose relay or individual, and the file holds that kind&#39;s classes only. Export twice if you need both. An ordinary event never sees the prompt.</p><p>In a relay export, each leg runner gets a row (or an entry) of their own, under their team and leg number. Entrants in a relay class who aren&#39;t on a team yet are included as well — an entry-per-person relay is a whole field of runners whose teams you have still to build, and leaving them out would lose them from the file.</p><h3 id="the-csv-round-trip" tabindex="-1">The CSV round trip <a class="header-anchor" href="#the-csv-round-trip" aria-label="Permalink to &quot;The CSV round trip&quot;">​</a></h3><p>The CSV is built to go back in. Its column headings are the ones Manager&#39;s CSV entry import already recognises, so the loop needs no column mapping:</p><ol><li><strong>Actions → Export entry list → Export CSV.</strong></li><li>Open it in a spreadsheet. Fix names, classes, clubs, cards, bibs.</li><li>Import it back through the <strong>Import Data</strong> dialog → <strong>Local Files</strong> → the <strong>Entries</strong> box. The columns map themselves; check the preview as usual and import.</li></ol><p><strong>Not every column comes back.</strong> The export writes more than the entry import reads, so be clear about which is which before you rely on it:</p><table tabindex="0"><thead><tr><th>Column</th><th>Comes back through the entry import?</th></tr></thead><tbody><tr><td><strong>Database Id</strong> (your own competitor number)</td><td>Yes</td></tr><tr><td><strong>First name</strong>, <strong>Surname</strong></td><td>Yes</td></tr><tr><td><strong>Class</strong></td><td>Yes — matched by name</td></tr><tr><td><strong>Club</strong></td><td>Yes — matched by name</td></tr><tr><td><strong>Country</strong></td><td>Yes, but only when the import has to <em>create</em> the club; an existing club keeps its own country</td></tr><tr><td><strong>Card</strong></td><td>Yes</td></tr><tr><td><strong>Bib</strong></td><td>Yes</td></tr><tr><td><strong>Ranking</strong></td><td><strong>No.</strong> Import the same file a <em>second</em> time through the <strong>Rankings</strong> box instead — the Ranking column maps itself there too, and the identity columns beside it are what it matches on.</td></tr><tr><td><strong>IOF Id</strong></td><td><strong>No.</strong> The CSV entry import has no IOF ID field at all. If IOF IDs have to travel, use the IOF XML or JSON export.</td></tr><tr><td><strong>Team name</strong>, <strong>Leg</strong> (relay exports only)</td><td><strong>No.</strong> Teams aren&#39;t rebuilt from a CSV. The runners return as competitors in the relay class and you re-assemble the teams — or use <a href="./relay-events#from-an-iof-entry-list-the-bib-convention">the bib convention</a>.</td></tr><tr><td><strong>Your custom fields</strong></td><td><strong>No.</strong> They&#39;re written so they&#39;re in front of you in the spreadsheet; the entry import doesn&#39;t read them back. If you have a custom field whose name Manager&#39;s own imports already use — <code>Rank</code>, <code>Class</code>, <code>Card</code>, <code>Start</code> and so on — its column is written as <em>Rank (custom)</em> to keep it apart from the real one, so the file never carries two headings that look like the same thing.</td></tr></tbody></table><p>So the round trip is a good way to correct <strong>who is entered and in what</strong> — not a way to move an event. It carries people, not the event&#39;s shape: a class named in the file that this event doesn&#39;t have is created with just that name, and nothing about its courses, its leg count or its mass start comes with it. Import the classes and courses properly first, then use the CSV for the entries.</p><p>Two things about the file itself. It is <strong>comma</strong>-delimited, and it is saved with a UTF-8 marker so Excel on Windows opens accented names properly instead of mangling them — if you re-save it from a spreadsheet, keep it as UTF-8 CSV. And a competitor with no ranking exports as a <strong>blank</strong> cell rather than a <code>0</code>: blank means &quot;this file says nothing about a ranking&quot;, while <code>0</code> means &quot;clear the stored one&quot;. See <a href="./import-event-data#clearing-a-ranking">Clearing a ranking</a>.</p><h3 id="what-the-iof-xml-file-leaves-out" tabindex="-1">What the IOF XML file leaves out <a class="header-anchor" href="#what-the-iof-xml-file-leaves-out" aria-label="Permalink to &quot;What the IOF XML file leaves out&quot;">​</a></h3><p>An IOF <code>EntryList</code> has nowhere to put some of what Manager holds. Those facts are left out of the file rather than tucked somewhere no other system would look for them:</p><ul><li><strong>Bib numbers</strong> — a competitor&#39;s and a team&#39;s alike.</li><li><strong>A course lock</strong>, and a <strong>fork variation</strong> — which course, or which fork of a forked course, someone is set to run. See <a href="./classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">Course pools and locking</a>.</li><li><strong>Your custom fields.</strong></li><li><strong>Where the entry came from</strong> — Eventor, a file import, or typed in by hand.</li><li><strong><a href="#notes">Notes</a></strong> — and these are left out of <em>every</em> export, on purpose; see below.</li></ul><p>A <a href="#ranking">ranking</a> <em>does</em> travel, as a score labelled as a rank, so rankings survive an IOF XML round trip in both directions.</p><p>If any of the rest has to travel, use <strong>Export JSON</strong>. It is the same document with all of it included — the bib, the ranking, the course and fork lock, your custom fields and the entry source. The one exception is <strong>Notes</strong>: they are your own remarks about the people in front of you, so no export carries them and nothing publishes them. Use a <a href="./../reference/backup-and-restore">backup</a> if the whole event has to move.</p><h2 id="the-clubs-page" tabindex="-1">The Clubs page <a class="header-anchor" href="#the-clubs-page" aria-label="Permalink to &quot;The Clubs page&quot;">​</a></h2><p>Navigate to <strong>Clubs</strong> in the <strong>Event Data</strong> section.</p><p>The table is read-only and lists the clubs that are actually used in this event:</p><ul><li><strong>Logo</strong> — the club logo, if one is available.</li><li><strong>Club</strong> — the club name.</li><li><strong>Short name</strong> — the abbreviation; its first four characters are used on Leaderboard when the club display is set to <em>Abbreviation</em>.</li><li><strong>Country</strong> — the ISO 3166-1 alpha-3 country code (e.g. <code>AUS</code>).</li></ul><p>Filter with <strong>Search Club Name</strong> or the <strong>Country</strong> filter. The page deliberately shows only clubs that at least one competitor references — so a club left behind by a re-import won&#39;t clutter the list.</p><h3 id="why-clubs-are-global" tabindex="-1">Why clubs are &quot;global&quot; <a class="header-anchor" href="#why-clubs-are-global" aria-label="Permalink to &quot;Why clubs are &quot;global&quot;&quot;">​</a></h3><p>Clubs live in a <strong>global Club Registry that spans every event</strong>, not inside a single event. Enter &quot;Newcastle Orienteering Club&quot; once and it&#39;s recognised in every future event, with the same short name and logo. Each event holds its own copy of the clubs its competitors use, merged on top of the shared cache so per-event tweaks don&#39;t leak elsewhere.</p><p>Because of this, you <strong>add and edit clubs in Settings, not on the Clubs page.</strong> Go to <strong>Settings → Club Registry</strong>, where you can:</p><ul><li><strong>Add club</strong> — name, short name, and country.</li><li><strong>Refresh clubs from Eventor</strong> — pull the known-clubs list from Eventor.</li><li><strong>Fetch default logos from Eventor</strong> — download club logos automatically.</li></ul><p>Click a club&#39;s name there to edit its short name, country, and logo. See the <a href="./../reference/club-registry">Club Registry</a> reference and <a href="./../reference/settings">Settings</a>.</p><h2 id="editing-many-competitors-at-once" tabindex="-1">Editing many competitors at once <a class="header-anchor" href="#editing-many-competitors-at-once" aria-label="Permalink to &quot;Editing many competitors at once&quot;">​</a></h2><p>Some jobs are the same small edit repeated: a ranking list has arrived for the elite classes, a club has handed in its members&#39; card numbers, a group needs start times allocated. Opening each competitor in turn works, but <strong>Actions → Bulk edit</strong> is built for it.</p><p>The dialog shows a grid — one row per competitor, and every cell an editor.</p><h3 id="choosing-what-you-can-see" tabindex="-1">Choosing what you can see <a class="header-anchor" href="#choosing-what-you-can-see" aria-label="Permalink to &quot;Choosing what you can see&quot;">​</a></h3><p>Only fields worth editing in bulk are offered, so the grid is not the whole competitor record. The <strong>columns button</strong> at the right-hand end of the header row turns them on and off, and headings can be dragged by their grip to reorder — the same header row as the Competitors page itself:</p><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Competitor</strong></td><td>Read-only, and always shown. It is how you keep your place in the grid.</td></tr><tr><td><strong>Class</strong></td><td></td></tr><tr><td><strong>Club</strong></td><td></td></tr><tr><td><strong>Course</strong></td><td>A picker only where the class has <a href="./classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">two or more courses in its pool</a>; elsewhere it just names the one course the class resolves to. Shown by default when the event has any such class.</td></tr><tr><td><strong>Variation</strong></td><td>The fork a competitor is locked to. Shown by default when a course has forks.</td></tr><tr><td><strong>Card</strong></td><td>A card number entered twice is flagged in amber — that is legal (a relay stick handed down the legs) but it is also how a typo shows itself.</td></tr><tr><td><strong>Bib</strong></td><td>Not editable for a relay runner: their bib comes from their team.</td></tr><tr><td><strong>Ranking</strong></td><td>See <a href="#ranking">Ranking</a> below.</td></tr><tr><td><strong>IOF ID</strong></td><td></td></tr><tr><td><strong>Allocated start time</strong></td><td>Not editable for a relay leg, which starts at the changeover.</td></tr><tr><td><strong>On start punch</strong></td><td>Whether a start-box punch may override the allocated time; <strong>Inherited</strong> means &quot;whatever the class or event says&quot;.</td></tr><tr><td><em>Custom fields</em></td><td>One column per <a href="./../reference/settings">custom competitor field</a>, if you have any.</td></tr></tbody></table><p>Your choice is remembered, so the dialog opens the way you left it next time.</p><h3 id="typing-your-way-down-the-grid" tabindex="-1">Typing your way down the grid <a class="header-anchor" href="#typing-your-way-down-the-grid" aria-label="Permalink to &quot;Typing your way down the grid&quot;">​</a></h3><p>Filling the grid in is nearly all typing, so it takes the keyboard:</p><ul><li><strong>Return</strong> moves to the next field along the row, and on to the next competitor at the end of it.</li><li><strong>Down arrow</strong> and <strong>up arrow</strong> move down and up the same column — the way to work through a column of card numbers, rankings or start times.</li></ul><p>Whatever is in the cell you land on is selected, so the first thing you type replaces it. Cells with nothing to type in are passed over rather than stopping you: the competitor&#39;s name, a relay runner&#39;s bib, a class with only one course.</p><p>A dropdown cell — <strong>Class</strong>, <strong>Course</strong>, <strong>Variation</strong>, <strong>On start punch</strong> — is passed through by the arrows in the same way, so a column of them can be walked without anything popping open. To open one, press <strong>Space</strong> or click it; or simply start typing the value, which picks the matching option without opening anything at all. <strong>Club</strong> searches as you type and offers a list. While any dropdown <em>is</em> open it owns the keys: the arrows move through its options and Return chooses one.</p><h3 id="setting-a-whole-column-at-once" tabindex="-1">Setting a whole column at once <a class="header-anchor" href="#setting-a-whole-column-at-once" aria-label="Permalink to &quot;Setting a whole column at once&quot;">​</a></h3><p>The common case is the same value for a group of people: everyone in a class onto a particular course, a club&#39;s runners moved to another class, a mass start time for a group. Narrow the grid with the filters below, then use the small <strong>set-column button</strong> in that column&#39;s heading. Pick the value and click <strong>Apply</strong> — it goes to every row the grid is showing, and no others.</p><p>It is offered on the columns where a shared value means something: <strong>Class</strong>, <strong>Club</strong>, <strong>Course</strong>, <strong>Variation</strong>, <strong>Allocated start time</strong>, <strong>On start punch</strong>, and any custom fields. It is deliberately <em>not</em> offered on <strong>Card</strong>, <strong>Bib</strong>, <strong>IOF ID</strong> or <strong>Ranking</strong> — those identify a person, so one value across a whole club is never what was wanted.</p><p>Rows the value cannot apply to are left alone, and the dialog says so when that happens: a course a class does not offer, or a start time on a relay leg. The button counts the rows it will actually change, so the number you see is what you get.</p><p>Like everything else in the dialog, nothing is written until you click <strong>Save</strong> — so if a fill goes somewhere you did not intend, <strong>Cancel</strong> undoes all of it.</p><h3 id="narrowing-the-list" tabindex="-1">Narrowing the list <a class="header-anchor" href="#narrowing-the-list" aria-label="Permalink to &quot;Narrowing the list&quot;">​</a></h3><p>The filters across the top scope the grid to the job: search by name or card, and pick <strong>any number</strong> of classes, clubs or statuses. &quot;All the elite classes&quot; is one selection, not four separate visits. The count beside the title tells you how many competitors are showing out of the whole event.</p><p>The filter is remembered per event, so you can close the dialog, do something else, and come back to the same set.</p><h3 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h3><p>Changed cells are <strong>highlighted</strong>, and a pencil appears against the row, so you can see at a glance what you have touched — including after you have moved on to the next field. Nothing is written until you click <strong>Save</strong>; <strong>Cancel</strong> discards the lot (it asks first if you have made changes).</p><p>Save applies every changed row in one request. If the server refuses one — a duplicate bib, a card number that is not valid, a course that is not in the class&#39;s pool — then:</p><ul><li>every other row is still saved, and stops being marked as changed;</li><li>the refused row keeps what you typed, and a <strong>Problem</strong> column appears with the reason;</li><li>the dialog stays open, with a <strong>Only rows with problems</strong> switch so you can work through just those rows;</li><li>fix them and click <strong>Save</strong> again.</li></ul><p>The dialog closes by itself once everything has saved.</p><h2 id="marking-non-starters-set-dns" tabindex="-1">Marking non-starters (Set DNS) <a class="header-anchor" href="#marking-non-starters-set-dns" aria-label="Permalink to &quot;Marking non-starters (Set DNS)&quot;">​</a></h2><p>After the start window closes you&#39;ll usually have entries who never turned up. Rather than editing each one, use <strong>Actions → Set competitors DNS</strong> on the Competitors page.</p><p>The dialog lets you select who to mark by status — typically those with <strong>no status yet</strong> or <strong>on course with no radio punches</strong> — optionally narrowed to particular classes, and shows how many competitors match. Confirm to set them all to <strong>Did Not Start</strong> in one go.</p><p><strong>DNS vs. delete:</strong> set <strong>DNS</strong> for someone who entered but didn&#39;t start — they stay in the results as a non-starter, which is what you usually want and what the <a href="./../running-the-event/safety-check">safety check</a> relies on. <strong>Delete</strong> only someone entered by mistake who should vanish entirely.</p><h2 id="clearing-the-whole-competitor-list" tabindex="-1">Clearing the whole competitor list <a class="header-anchor" href="#clearing-the-whole-competitor-list" aria-label="Permalink to &quot;Clearing the whole competitor list&quot;">​</a></h2><p><strong>Actions → Delete all competitors</strong> empties the list in one step. Use it when an import went in wrong and you want to start the entry list again from a clean slate — it&#39;s much quicker than deleting entries one at a time.</p><p>Manager confirms first and lists what else changes, because the effects reach beyond the list you&#39;re looking at:</p><ul><li>Every competitor goes, along with their result, status, start time and any punch corrections.</li><li>Card downloads and radio punches are <strong>kept</strong> — they&#39;re records of what happened at the event, not of who entered — but they&#39;re no longer assigned to anybody. Re-importing the entry list and re-assigning the downloads gets the results back.</li><li>In a relay event the teams stay, but their legs are left without runners.</li><li>Classes, courses, clubs and controls are untouched.</li></ul><p>There is no undo. On a live event, <a href="./../reference/backup-and-restore">back the event up</a> before you do this.</p><p>Relay teams have the same action on the Teams page (<strong>Actions → Delete all teams</strong>). Deleting the teams keeps the runners as competitors, but they lose the bib number and leg they inherited from their team.</p><h2 id="late-entries-and-on-the-day-registration" tabindex="-1">Late entries and on-the-day registration <a class="header-anchor" href="#late-entries-and-on-the-day-registration" aria-label="Permalink to &quot;Late entries and on-the-day registration&quot;">​</a></h2><p>Adding a competitor after the event is under way works exactly the same as above — <strong>Actions → Add</strong>, or let a card download create the entry. Manager doesn&#39;t lock the competitor list once the event starts. For the registration-desk workflow and assigning start times on the day, see <a href="./../running-the-event/late-entries">Late entries</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./import-event-data">Importing event data</a> — the usual way to populate competitors and clubs</li><li><a href="./../after-the-event/exports">Exporting data</a> — the event&#39;s other exports, results included</li><li><a href="./relay-events">Relay events</a> — teams, legs, and why a mixed event exports one kind at a time</li><li><a href="./classes-and-courses">Classes and courses</a> — the classes competitors are assigned to, and course pools</li><li><a href="./start-times">Start times</a> — allocating and overriding start times</li><li><a href="./start-draw#honouring-start-requests">The start draw</a> — the one thing that acts on a start request, and only when you ask it to</li><li><a href="./../reference/competitor-registry">Competitor Registry</a> — the cross-event store of known competitors</li><li><a href="./../reference/club-registry">Club Registry</a> — the cross-event store of clubs</li><li><a href="./../running-the-event/card-download">Downloading cards</a> — how a download attaches to a competitor</li><li><a href="./../running-the-event/late-entries">Late entries</a> — adding competitors on event day</li></ul>',126)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
